import type {
  ComponentStyleSlots,
  ComponentStyleVariantConfig,
  Theme,
  ThemeComponentVariants,
} from "@types";

import React, { useId } from "react";
import { merge } from "lodash-es";

export const useUniqueId = (prefix: string = "") => {
  const id = useId();
  return `exp-textura-${prefix}_${id}`;
};

export const getExcludedDOMProps = (...exludeProps: string[]): string[] => {
  // If more global component props are added, add them here and the ComponentProps interface
  return [...exludeProps, "as", "styleSlots", "currentTheme", "variant"];
};

export function getStyleSlots<T = ComponentStyleSlots>(
  componentName: keyof ThemeComponentVariants,
  currentTheme: Theme | undefined,
  compVariant: string | undefined,
  styleSlots: ComponentStyleSlots | undefined,
  variantConfig?: ComponentStyleVariantConfig,
) {
  const theme = currentTheme,
    variant = compVariant || "default",
    defaultComponentVariant = theme?.componentVariants?.[componentName]?.default,
    componentVariant = theme?.componentVariants?.[componentName]?.[variant];

  const defaultVariant = variantConfig?.default || {};

  const variantSettings = merge(
    {},
    defaultVariant,
    defaultComponentVariant,
    variantConfig?.[variant],
    componentVariant,
    styleSlots,
  );

  return variantSettings as T;
}

export const getTransitionDurationInMs = (element: Element) => {
  const computedStyle = getComputedStyle(element);
  const transitionDuration = computedStyle.transitionDuration;

  let durationInMs;

  if (transitionDuration.includes("ms")) {
    durationInMs = parseFloat(transitionDuration);
  } else if (transitionDuration.includes("s")) {
    durationInMs = parseFloat(transitionDuration) * 1000;
  } else {
    durationInMs = 0;
  }
  return durationInMs;
};

export const flattenChildren = (children: React.ReactNode): React.ReactNode[] => {
  const flattened: React.ReactNode[] = [];
  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child) && child.type === React.Fragment) {
      flattened.push(...flattenChildren(child.props.children));
    } else {
      flattened.push(child);
    }
  });
  return flattened;
};
